#[derive(Debug, Clone, PartialEq, serde::Serialize)]
pub struct RepeatedNameScan {
    pub seen: Rc<HashMap<Symbol, bool>>,
    pub repeated: Rc<Vec<Rc<Edge>>>,
}

pub fn repeated_name_edges(children: Rc<Vec<Rc<Edge>>>) -> Rc<Vec<Rc<Edge>>> {
    {
        let scanned = children.iter().cloned().fold(Rc::new(RepeatedNameScan {
    seen: v1_rt::rc_empty_map::<_, _>(),
    repeated: Rc::new(vec![]),
}), |acc: Rc<RepeatedNameScan>, e: Rc<Edge>| match (*e.label.clone()).clone() {
    EdgeLabel::StructuralLabel { label: _, .. } => acc.clone(),
    EdgeLabel::Positional => acc.clone(),
    EdgeLabel::Authored { name: n, .. } => match v1_rt::lookup(&acc.seen.clone(), n.clone()) {
    Some(_) => Rc::new(RepeatedNameScan {
    seen: acc.seen.clone(),
    repeated: crate::std_algebra::list_snoc_item(acc.repeated.clone(), e.clone()),
}),
    std::option::Option::None => Rc::new(RepeatedNameScan {
    seen: v1_rt::rc_map_insert(acc.seen.clone(), n.clone(), true),
    repeated: acc.repeated.clone(),
}),
},
});
scanned.repeated.clone()
}
}

pub fn repeated_authored_name_optional(children: Rc<Vec<Rc<Edge>>>) -> Option<std::string::String> {
    match crate::std_algebra::list_head(repeated_name_edges(children)) {
    Some(e) => match (*e.label.clone()).clone() {
    EdgeLabel::Authored { name: n, .. } => Some(n.clone()),
    EdgeLabel::Positional => std::option::Option::None,
    EdgeLabel::StructuralLabel { label: _, .. } => std::option::Option::None,
},
    std::option::Option::None => std::option::Option::None,
}
}

pub fn conj_children_optional(n: Rc<Node>) -> Option<Rc<Vec<Rc<Edge>>>> {
    match (*n.kind.clone()).clone() {
    NodeKind::TypeNode { connective: ref __rc_connective, .. } => { match __rc_connective.as_ref() {
    Connective::Conj => Some(n.children.clone()),
    Connective::Atom { identity: _, .. } => std::option::Option::None,
    Connective::Disj => std::option::Option::None,
    Connective::Arrow => std::option::Option::None,
    Connective::Instantiation => std::option::Option::None,
} },
    NodeKind::ComputationNode { behavior: _, .. } => std::option::Option::None,
}
}

pub fn equality_derived_declared_field(a: Rc<DeclaredField>, b: Rc<DeclaredField>) -> bool {
    ((((a.name.clone() == b.name.clone()) && crate::v2_std_node::node_equal_ignoring_provenance(a.type_node.clone(), b.type_node.clone())) && (a.cardinality.clone() == b.cardinality.clone())) && crate::std_optional::optional_eq(a.default.clone(), b.default.clone(), |eqp0, eqq0| crate::v2_std_node::node_equal_ignoring_provenance(eqp0.clone(), eqq0.clone())))
}

pub fn equality_derived_binder_parts(a: Rc<BinderParts>, b: Rc<BinderParts>) -> bool {
    (crate::v2_std_node::node_equal_ignoring_provenance(a.type_node.clone(), b.type_node.clone()) && crate::std_optional::optional_eq(a.default.clone(), b.default.clone(), |eqp0, eqq0| crate::v2_std_node::node_equal_ignoring_provenance(eqp0.clone(), eqq0.clone())))
}

pub fn equality_derived_binder_parts_read(a: Rc<BinderPartsRead>, b: Rc<BinderPartsRead>) -> bool {
    ((crate::std_optional::optional_eq(a.type_node.clone(), b.type_node.clone(), |eqp0, eqq0| crate::v2_std_node::node_equal_ignoring_provenance(eqp0.clone(), eqq0.clone())) && crate::std_optional::optional_eq(a.default.clone(), b.default.clone(), |eqp0, eqq0| crate::v2_std_node::node_equal_ignoring_provenance(eqp0.clone(), eqq0.clone()))) && (a.foreign.clone() == b.foreign.clone()))
}

pub fn equality_derived_construct_tag_reading(a: Rc<ConstructTagReading>, b: Rc<ConstructTagReading>) -> bool {
    match (*a.clone()).clone() {
    ConstructTagReading::ConstructTagAuthored { reference: eqa_reference, .. } => match (*b.clone()).clone() {
    ConstructTagReading::ConstructTagAuthored { reference: eqb_reference, .. } => crate::v2_std_node::node_equal_ignoring_provenance(eqa_reference.clone(), eqb_reference.clone()),
    _ => false,
},
    ConstructTagReading::ConstructTagElided => match (*b.clone()).clone() {
    ConstructTagReading::ConstructTagElided => true,
    _ => false,
},
    ConstructTagReading::NotAConstruct => match (*b.clone()).clone() {
    ConstructTagReading::NotAConstruct => true,
    _ => false,
},
}
}

pub fn equality_derived_field_projection(a: Rc<FieldProjection>, b: Rc<FieldProjection>) -> bool {
    (crate::v2_std_node::node_equal_ignoring_provenance(a.base.clone(), b.base.clone()) && (a.field.clone() == b.field.clone()))
}

pub fn equality_derived_named_child_lookup(a: Rc<NamedChildLookup>, b: Rc<NamedChildLookup>) -> bool {
    match (*a.clone()).clone() {
    NamedChildLookup::NamedChildFound { target: eqa_target, .. } => match (*b.clone()).clone() {
    NamedChildLookup::NamedChildFound { target: eqb_target, .. } => crate::v2_std_node::node_equal_ignoring_provenance(eqa_target.clone(), eqb_target.clone()),
    _ => false,
},
    NamedChildLookup::NamedChildMissing => match (*b.clone()).clone() {
    NamedChildLookup::NamedChildMissing => true,
    _ => false,
},
    NamedChildLookup::NamedChildAmbiguous => match (*b.clone()).clone() {
    NamedChildLookup::NamedChildAmbiguous => true,
    _ => false,
},
}
}

pub fn equality_derived_repeated_name_scan(a: Rc<RepeatedNameScan>, b: Rc<RepeatedNameScan>) -> bool {
    ((a.seen.clone() == b.seen.clone()) && crate::std_algebra::zip_eq(a.repeated.clone(), b.repeated.clone(), |eqp0, eqq0| crate::v2_std_node::node_edge_equal_ignoring_provenance(eqp0.clone(), eqq0.clone())))
}
